Problem:
A car manufacturing company needs to distribute their cars to their retail stores by either large trailers or small trailers. A large trailer can carry 6 cars while a small trailer can carry 4 cars. Since large trailers are harder to get a hold of, the number of small trailers used has to be at least three times the number of large trailers used. If at least 80 cars need to be transported, minimize the total number of trailers needed.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "large trailers used",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "small trailers used",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "large trailers used",
     "coef": 1.0
    },
    {
     "var": "small trailers used",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "small_at_least_three_times_large",
    "terms": [
     {
      "var": "small trailers used",
      "coef": 1.0
     },
     {
      "var": "large trailers used",
      "coef": -3.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "cars_transported",
    "terms": [
     {
      "var": "large trailers used",
      "coef": 6.0
     },
     {
      "var": "small trailers used",
      "coef": 4.0
     }
    ],
    "sense": ">=",
    "rhs": 80.0
   }
  ]
 },
 "facts": {
  "objective": 18.0,
  "values": {
   "large trailers used": 4.0,
   "small trailers used": 14.0
  },
  "binding": [
   "cars_transported"
  ],
  "slack": {
   "small_at_least_three_times_large": 2.0,
   "cars_transported": 0.0
  },
  "shadow_prices": null
 }
}
